namespace sv_caa681d09137438eafd5817b8d2a9e93.Services;

public record UserProfile(string DisplayName, string Email, string AvatarUrl, string Bio);
public record NotificationPrefs(bool EmailNotifications, bool PushNotifications, bool WeeklyDigest, List<string> MutedChannels);
public record SecuritySettings(bool TwoFactorEnabled, DateTime? LastPasswordChange, List<ActiveSession> Sessions);
public record ActiveSession(string Id, string Device, string Location, DateTime LastActive);
public record AppearanceSettings(string Theme, string FontSize, string Language, bool CompactMode);

public interface ISettingsService
{
    Task<UserProfile> GetProfileAsync();
    Task SaveProfileAsync(UserProfile profile);
    Task<NotificationPrefs> GetNotificationPrefsAsync();
    Task SaveNotificationPrefsAsync(NotificationPrefs prefs);
    Task<SecuritySettings> GetSecuritySettingsAsync();
    Task ChangePasswordAsync(string currentPassword, string newPassword);
    Task RevokeSessionAsync(string sessionId);
    Task<AppearanceSettings> GetAppearanceAsync();
    Task SaveAppearanceAsync(AppearanceSettings settings);
}

@page "/settings"
@using sv_caa681d09137438eafd5817b8d2a9e93.Services
@inject ISettingsService SettingsService
@rendermode InteractiveServer

<PageTitle>Settings</PageTitle>

<div class="settings-dashboard">
    <nav class="settings-sidebar">
        <ul>
            <li class="@(activeSection == "Profile" ? "active" : "")" @onclick='() => SetSection("Profile")'>
                <span class="nav-icon">👤</span> Profile
            </li>
            <li class="@(activeSection == "Notifications" ? "active" : "")" @onclick='() => SetSection("Notifications")'>
                <span class="nav-icon">🔔</span> Notifications
            </li>
            <li class="@(activeSection == "Security" ? "active" : "")" @onclick='() => SetSection("Security")'>
                <span class="nav-icon">🔒</span> Security
            </li>
            <li class="@(activeSection == "Appearance" ? "active" : "")" @onclick='() => SetSection("Appearance")'>
                <span class="nav-icon">🎨</span> Appearance
            </li>
        </ul>
    </nav>

    <main class="settings-content">
        @if (isLoading)
        {
            <div class="loading-spinner">Loading...</div>
        }
        else
        {
            @switch (activeSection)
            {
                case "Profile":
                    <ProfileSection />
                    break;
                case "Notifications":
                    <NotificationsSection />
                    break;
                case "Security":
                    <SecuritySection />
                    break;
                case "Appearance":
                    <AppearanceSection />
                    break;
            }
        }

        @if (!string.IsNullOrEmpty(toastMessage))
        {
            <div class="toast @toastType">
                @toastMessage
                <button class="toast-close" @onclick="DismissToast">✕</button>
            </div>
        }
    </main>
</div>

@* ===== PROFILE SECTION ===== *@
@{ RenderFragment ProfileSection = __builder =>
{
    <section class="settings-section">
        <h2>Profile Settings</h2>

        <div class="avatar-preview">
            <img src="@editProfile.AvatarUrl" alt="Avatar" class="avatar-img" />
            <span class="avatar-url">@editProfile.AvatarUrl</span>
        </div>

        <div class="form-group">
            <label for="displayName">Display Name</label>
            <input id="displayName" type="text" @bind="editProfile.DisplayName" />
        </div>

        <div class="form-group">
            <label for="email">Email</label>
            <input id="email" type="email" @bind="editProfile.Email" />
        </div>

        <div class="form-group">
            <label for="bio">Bio</label>
            <textarea id="bio" rows="4" @bind="editProfile.Bio"></textarea>
        </div>

        <div class="form-group">
            <label for="avatarUrl">Avatar URL</label>
            <input id="avatarUrl" type="url" @bind="editProfile.AvatarUrl" />
        </div>

        <div class="button-group">
            <button class="btn btn-primary" @onclick="SaveProfile">Save Changes</button>
            <button class="btn btn-secondary" @onclick="DiscardProfileChanges">Discard Changes</button>
        </div>
    </section>
}; }

@* ===== NOTIFICATIONS SECTION ===== *@
@{ RenderFragment NotificationsSection = __builder =>
{
    <section class="settings-section">
        <h2>Notification Preferences</h2>

        <div class="toggle-group">
            <label class="toggle-label">
                <input type="checkbox" @bind="editNotifications.EmailNotifications" />
                <span class="toggle-switch"></span>
                Email Notifications
            </label>
        </div>

        <div class="toggle-group">
            <label class="toggle-label">
                <input type="checkbox" @bind="editNotifications.PushNotifications" />
                <span class="toggle-switch"></span>
                Push Notifications
            </label>
        </div>

        <div class="toggle-group">
            <label class="toggle-label">
                <input type="checkbox" @bind="editNotifications.WeeklyDigest" />
                <span class="toggle-switch"></span>
                Weekly Digest
            </label>
        </div>

        <h3>Muted Channels</h3>
        <div class="channel-list">
            @foreach (var channel in availableChannels)
            {
                var isMuted = editNotifications.MutedChannels.Contains(channel);
                <label class="channel-item">
                    <input type="checkbox" checked="@isMuted"
                           @onchange="(e) => ToggleMuteChannel(channel, (bool)(e.Value ?? false))" />
                    @channel
                </label>
            }
        </div>

        <div class="button-group">
            <button class="btn btn-primary" @onclick="SaveNotifications">Save Preferences</button>
        </div>
    </section>
}; }

@* ===== SECURITY SECTION ===== *@
@{ RenderFragment SecuritySection = __builder =>
{
    <section class="settings-section">
        <h2>Security Settings</h2>

        <div class="expandable-panel">
            <button class="panel-header" @onclick="TogglePasswordPanel">
                <span>Change Password</span>
                <span class="expand-icon">@(showPasswordPanel ? "▾" : "▸")</span>
            </button>

            @if (showPasswordPanel)
            {
                <div class="panel-body">
                    <div class="form-group">
                        <label for="currentPassword">Current Password</label>
                        <input id="currentPassword" type="password" @bind="currentPassword" />
                    </div>
                    <div class="form-group">
                        <label for="newPassword">New Password</label>
                        <input id="newPassword" type="password" @bind="newPassword" />
                    </div>
                    <div class="form-group">
                        <label for="confirmPassword">Confirm Password</label>
                        <input id="confirmPassword" type="password" @bind="confirmPassword" />
                    </div>
                    <button class="btn btn-primary" @onclick="UpdatePassword">Update Password</button>
                </div>
            }
        </div>

        <div class="toggle-group security-toggle">
            <label class="toggle-label">
                <input type="checkbox" checked="@securitySettings?.TwoFactorEnabled" disabled />
                <span class="toggle-switch"></span>
                Two-Factor Authentication
                <span class="status-indicator @(securitySettings?.TwoFactorEnabled == true ? "status-enabled" : "status-disabled")">
                    @(securitySettings?.TwoFactorEnabled == true ? "Enabled" : "Disabled")
                </span>
            </label>
            @if (securitySettings?.LastPasswordChange != null)
            {
                <p class="last-change">Last password change: @securitySettings.LastPasswordChange.Value.ToString("MMMM dd, yyyy")</p>
            }
        </div>

        <h3>Active Sessions</h3>
        <div class="sessions-table-wrapper">
            <table class="sessions-table">
                <thead>
                    <tr>
                        <th>Device</th>
                        <th>Location</th>
                        <th>Last Active</th>
                        <th>Action</th>
                    </tr>
                </thead>
                <tbody>
                    @if (securitySettings?.Sessions != null)
                    {
                        @foreach (var session in securitySettings.Sessions)
                        {
                            <tr>
                                <td>@session.Device</td>
                                <td>@session.Location</td>
                                <td>@session.LastActive.ToString("g")</td>
                                <td>
                                    @if (session != securitySettings.Sessions.FirstOrDefault())
                                    {
                                        <button class="btn btn-danger btn-sm"
                                                @onclick="() => ConfirmRevokeSession(session)">
                                            Revoke
                                        </button>
                                    }
                                    else
                                    {
                                        <span class="current-badge">Current</span>
                                    }
                                </td>
                            </tr>
                        }
                    }
                </tbody>
            </table>
        </div>

        @if (showRevokeConfirmation)
        {
            <div class="modal-overlay" @onclick="CancelRevoke">
                <div class="modal-dialog" @onclick:stopPropagation>
                    <h3>Confirm Session Revocation</h3>
                    <p>Are you sure you want to revoke the session on <strong>@sessionToRevoke?.Device</strong> from <strong>@sessionToRevoke?.Location</strong>?</p>
                    <div class="button-group">
                        <button class="btn btn-danger" @onclick="RevokeSession">Revoke Session</button>
                        <button class="btn btn-secondary" @onclick="CancelRevoke">Cancel</button>
                    </div>
                </div>
            </div>
        }
    </section>
}; }

@* ===== APPEARANCE SECTION ===== *@
@{ RenderFragment AppearanceSection = __builder =>
{
    <section class="settings-section">
        <h2>Appearance Settings</h2>

        <div class="form-group">
            <label>Theme</label>
            <div class="radio-group">
                <label class="radio-label">
                    <input type="radio" name="theme" value="Light"
                           checked="@(editAppearance.Theme == "Light")"
                           @onchange='() => editAppearance.Theme = "Light"' /> Light
                </label>
                <label class="radio-label">
                    <input type="radio" name="theme" value="Dark"
                           checked="@(editAppearance.Theme == "Dark")"
                           @onchange='() => editAppearance.Theme = "Dark"' /> Dark
                </label>
                <label class="radio-label">
                    <input type="radio" name="theme" value="System"
                           checked="@(editAppearance.Theme == "System")"
                           @onchange='() => editAppearance.Theme = "System"' /> System
                </label>
            </div>
        </div>

        <div class="form-group">
            <label>Font Size</label>
            <div class="radio-group">
                <label class="radio-label">
                    <input type="radio" name="fontSize" value="Small"
                           checked="@(editAppearance.FontSize == "Small")"
                           @onchange='() => editAppearance.FontSize = "Small"' /> Small
                </label>
                <label class="radio-label">
                    <input type="radio" name="fontSize" value="Medium"
                           checked="@(editAppearance.FontSize == "Medium")"
                           @onchange='() => editAppearance.FontSize = "Medium"' /> Medium
                </label>
                <label class="radio-label">
                    <input type="radio" name="fontSize" value="Large"
                           checked="@(editAppearance.FontSize == "Large")"
                           @onchange='() => editAppearance.FontSize = "Large"' /> Large
                </label>
            </div>
        </div>

        <div class="form-group">
            <label for="language">Language</label>
            <select id="language" @bind="editAppearance.Language">
                <option value="en">English</option>
                <option value="es">Spanish</option>
                <option value="fr">French</option>
                <option value="de">German</option>
                <option value="ja">Japanese</option>
                <option value="zh">Chinese</option>
            </select>
        </div>

        <div class="toggle-group">
            <label class="toggle-label">
                <input type="checkbox" @bind="editAppearance.CompactMode" />
                <span class="toggle-switch"></span>
                Compact Mode
            </label>
        </div>

        <h3>Live Preview</h3>
        <div class="live-preview @GetPreviewClasses()">
            <div class="preview-header">Sample Header</div>
            <p class="preview-text">This is how your content will look with the selected appearance settings.</p>
            <button class="preview-button">Sample Button</button>
        </div>

        <div class="button-group">
            <button class="btn btn-primary" @onclick="SaveAppearance">Save</button>
        </div>
    </section>
}; }

@code {
    private string activeSection = "Profile";
    private bool isLoading = true;
    private string toastMessage = "";
    private string toastType = "";

    // Profile state
    private EditableProfile editProfile = new();
    private UserProfile? savedProfile;

    // Notifications state
    private EditableNotifications editNotifications = new();
    private List<string> availableChannels = new() { "general", "announcements", "updates", "marketing", "engineering" };

    // Security state
    private SecuritySettings? securitySettings;
    private bool showPasswordPanel;
    private string currentPassword = "";
    private string newPassword = "";
    private string confirmPassword = "";
    private bool showRevokeConfirmation;
    private ActiveSession? sessionToRevoke;

    // Appearance state
    private EditableAppearance editAppearance = new();

    protected override async Task OnInitializedAsync()
    {
        await LoadSectionData();
    }

    private async Task SetSection(string section)
    {
        activeSection = section;
        isLoading = true;
        await LoadSectionData();
    }

    private async Task LoadSectionData()
    {
        try
        {
            switch (activeSection)
            {
                case "Profile":
                    savedProfile = await SettingsService.GetProfileAsync();
                    editProfile = EditableProfile.FromProfile(savedProfile);
                    break;
                case "Notifications":
                    var prefs = await SettingsService.GetNotificationPrefsAsync();
                    editNotifications = EditableNotifications.FromPrefs(prefs);
                    break;
                case "Security":
                    securitySettings = await SettingsService.GetSecuritySettingsAsync();
                    break;
                case "Appearance":
                    var appearance = await SettingsService.GetAppearanceAsync();
                    editAppearance = EditableAppearance.FromSettings(appearance);
                    break;
            }
        }
        finally
        {
            isLoading = false;
        }
    }

    // Profile methods
    private async Task SaveProfile()
    {
        var profile = new UserProfile(editProfile.DisplayName, editProfile.Email, editProfile.AvatarUrl, editProfile.Bio);
        await SettingsService.SaveProfileAsync(profile);
        savedProfile = profile;
        ShowToast("Profile saved successfully!", "success");
    }

    private void DiscardProfileChanges()
    {
        if (savedProfile != null)
        {
            editProfile = EditableProfile.FromProfile(savedProfile);
        }
    }

    // Notifications methods
    private void ToggleMuteChannel(string channel, bool muted)
    {
        if (muted && !editNotifications.MutedChannels.Contains(channel))
            editNotifications.MutedChannels.Add(channel);
        else if (!muted)
            editNotifications.MutedChannels.Remove(channel);
    }

    private async Task SaveNotifications()
    {
        var prefs = new NotificationPrefs(
            editNotifications.EmailNotifications,
            editNotifications.PushNotifications,
            editNotifications.WeeklyDigest,
            new List<string>(editNotifications.MutedChannels));
        await SettingsService.SaveNotificationPrefsAsync(prefs);
        ShowToast("Notification preferences saved!", "success");
    }

    // Security methods
    private void TogglePasswordPanel() => showPasswordPanel = !showPasswordPanel;

    private async Task UpdatePassword()
    {
        if (string.IsNullOrWhiteSpace(newPassword) || newPassword != confirmPassword)
        {
            ShowToast("Passwords do not match.", "error");
            return;
        }

        await SettingsService.ChangePasswordAsync(currentPassword, newPassword);
        currentPassword = "";
        newPassword = "";
        confirmPassword = "";
        showPasswordPanel = false;
        ShowToast("Password updated successfully!", "success");
    }

    private void ConfirmRevokeSession(ActiveSession session)
    {
        sessionToRevoke = session;
        showRevokeConfirmation = true;
    }

    private async Task RevokeSession()
    {
        if (sessionToRevoke != null)
        {
            await SettingsService.RevokeSessionAsync(sessionToRevoke.Id);
            securitySettings = await SettingsService.GetSecuritySettingsAsync();
            ShowToast("Session revoked.", "success");
        }
        CancelRevoke();
    }

    private void CancelRevoke()
    {
        showRevokeConfirmation = false;
        sessionToRevoke = null;
    }

    // Appearance methods
    private string GetPreviewClasses()
    {
        var classes = $"preview-theme-{editAppearance.Theme.ToLowerInvariant()} preview-font-{editAppearance.FontSize.ToLowerInvariant()}";
        if (editAppearance.CompactMode) classes += " preview-compact";
        return classes;
    }

    private async Task SaveAppearance()
    {
        var settings = new AppearanceSettings(editAppearance.Theme, editAppearance.FontSize, editAppearance.Language, editAppearance.CompactMode);
        await SettingsService.SaveAppearanceAsync(settings);
        ShowToast("Appearance settings saved!", "success");
    }

    // Toast
    private void ShowToast(string message, string type)
    {
        toastMessage = message;
        toastType = type;
        _ = DismissToastAfterDelay();
    }

    private async Task DismissToastAfterDelay()
    {
        await Task.Delay(3000);
        toastMessage = "";
        await InvokeAsync(StateHasChanged);
    }

    private void DismissToast()
    {
        toastMessage = "";
    }

    // Editable models
    private class EditableProfile
    {
        public string DisplayName { get; set; } = "";
        public string Email { get; set; } = "";
        public string AvatarUrl { get; set; } = "";
        public string Bio { get; set; } = "";

        public static EditableProfile FromProfile(UserProfile p) => new()
        {
            DisplayName = p.DisplayName,
            Email = p.Email,
            AvatarUrl = p.AvatarUrl,
            Bio = p.Bio
        };
    }

    private class EditableNotifications
    {
        public bool EmailNotifications { get; set; }
        public bool PushNotifications { get; set; }
        public bool WeeklyDigest { get; set; }
        public List<string> MutedChannels { get; set; } = new();

        public static EditableNotifications FromPrefs(NotificationPrefs p) => new()
        {
            EmailNotifications = p.EmailNotifications,
            PushNotifications = p.PushNotifications,
            WeeklyDigest = p.WeeklyDigest,
            MutedChannels = new List<string>(p.MutedChannels)
        };
    }

    private class EditableAppearance
    {
        public string Theme { get; set; } = "System";
        public string FontSize { get; set; } = "Medium";
        public string Language { get; set; } = "en";
        public bool CompactMode { get; set; }

        public static EditableAppearance FromSettings(AppearanceSettings s) => new()
        {
            Theme = s.Theme,
            FontSize = s.FontSize,
            Language = s.Language,
            CompactMode = s.CompactMode
        };
    }
}

