@using sv_caa681d09137438eafd5817b8d2a9e93.Services
@inject ISettingsService SettingsService
@rendermode InteractiveServer

<PageTitle>Settings</PageTitle>

<div class="settings-dashboard">
    <nav class="settings-sidebar">
        <ul>
            <li class="@(activeSection == "Profile" ? "active" : "")" @onclick='() => SetSection("Profile")'>
                <span class="nav-icon">👤</span> Profile
            </li>
            <li class="@(activeSection == "Notifications" ? "active" : "")" @onclick='() => SetSection("Notifications")'>
                <span class="nav-icon">🔔</span> Notifications
            </li>
            <li class="@(activeSection == "Security" ? "active" : "")" @onclick='() => SetSection("Security")'>
                <span class="nav-icon">🔒</span> Security
            </li>
            <li class="@(activeSection == "Appearance" ? "active" : "")" @onclick='() => SetSection("Appearance")'>
                <span class="nav-icon">🎨</span> Appearance
            </li>
        </ul>
    </nav>

    <main class="settings-content">
        @if (isLoading)
        {
            <div class="loading-spinner">Loading...</div>
        }
        else if (activeSection == "Profile")
        {
            <section class="settings-section">
                <h2>Profile Settings</h2>

                <div class="avatar-preview">
                    <img src="@editProfile.AvatarUrl" alt="Avatar" class="avatar-img" />
                    <span class="avatar-url">@editProfile.AvatarUrl</span>
                </div>

                <div class="form-group">
                    <label for="displayName">Display Name</label>
                    <input id="displayName" type="text" @bind="editProfile.DisplayName" />
                </div>

                <div class="form-group">
                    <label for="email">Email</label>
                    <input id="email" type="email" @bind="editProfile.Email" />
                </div>

                <div class="form-group">
                    <label for="bio">Bio</label>
                    <textarea id="bio" rows="4" @bind="editProfile.Bio"></textarea>
                </div>

                <div class="form-group">
                    <label for="avatarUrl">Avatar URL</label>
                    <input id="avatarUrl" type="url" @bind="editProfile.AvatarUrl" />
                </div>

                <div class="button-group">
                    <button class="btn btn-primary" @onclick="SaveProfile">Save Changes</button>
                    <button class="btn btn-secondary" @onclick="DiscardProfileChanges">Discard Changes</button>
                </div>
            </section>
        }
        else if (activeSection == "Notifications")
        {
            <section class="settings-section">
                <h2>Notification Preferences</h2>

                <div class="toggle-group">
                    <label class="toggle-label">
                        <input type="checkbox" @bind="editNotifications.EmailNotifications" />
                        <span class="toggle-switch"></span>
                        Email Notifications
                    </label>
                </div>

                <div class="toggle-group">
                    <label class="toggle-label">
                        <input type="checkbox" @bind="editNotifications.PushNotifications" />
                        <span class="toggle-switch"></span>
                        Push Notifications
                    </label>
                </div>

                <div class="toggle-group">
                    <label class="toggle-label">
                        <input type="checkbox" @bind="editNotifications.WeeklyDigest" />
                        <span class="toggle-switch"></span>
                        Weekly Digest
                    </label>
                </div>

                <h3>Muted Channels</h3>
                <div class="channel-list">
                    @foreach (var channel in availableChannels)
                    {
                        var ch = channel;
                        var isMuted = editNotifications.MutedChannels.Contains(ch);
                        <label class="channel-item">
                            <input type="checkbox" checked="@isMuted"
                                   @onchange="(e) => ToggleMuteChannel(ch, (bool)(e.Value ?? false))" />
                            @ch
                        </label>
                    }
                </div>

                <div class="button-group">
                    <button class="btn btn-primary" @onclick="SaveNotifications">Save Preferences</button>
                </div>
            </section>
        }
        else if (activeSection == "Security")
        {
            <section class="settings-section">
                <h2>Security Settings</h2>

                <div class="expandable-panel">
                    <button class="panel-header" @onclick="TogglePasswordPanel">
                        <span>Change Password</span>
                        <span class="expand-icon">@(showPasswordPanel ? "▾" : "▸")</span>
                    </button>

                    @if (showPasswordPanel)
                    {
                        <div class="panel-body">
                            <div class="form-group">
                                <label for="currentPassword">Current Password</label>
                                <input id="currentPassword" type="password" @bind="currentPassword" />
                            </div>
                            <div class="form-group">
                                <label for="newPassword">New Password</label>
                                <input id="newPassword" type="password" @bind="newPassword" />
                            </div>
                            <div class="form-group">
                                <label for="confirmPassword">Confirm Password</label>
                                <input id="confirmPassword" type="password" @bind="confirmPassword" />
                            </div>
                            <button class="btn btn-primary" @onclick="UpdatePassword">Update Password</button>
                        </div>
                    }
                </div>

                <div class="toggle-group security-toggle">
                    <label class="toggle-label">
                        <input type="checkbox" checked="@(securitySettings?.TwoFactorEnabled ?? false)" disabled />
                        <span class="toggle-switch"></span>
                        Two-Factor Authentication
                        <span class="status-indicator @(securitySettings?.TwoFactorEnabled == true ? "status-enabled" : "status-disabled")">
                            @(securitySettings?.TwoFactorEnabled == true ? "Enabled" : "Disabled")
                        </span>
                    </label>
                    @if (securitySettings?.LastPasswordChange != null)
                    {
                        <p class="last-change">Last password change: @securitySettings.LastPasswordChange.Value.ToString("MMMM dd, yyyy")</p>
                    }
                </div>

                <h3>Active Sessions</h3>
                <div class="sessions-table-wrapper">
                    <table class="sessions-table">
                        <thead>
                            <tr>
                                <th>Device</th>
                                <th>Location</th>
                                <th>Last Active</th>
                                <th>Action</th>
                            </tr>
                        </thead>
                        <tbody>
                            @if (securitySettings?.Sessions != null)
                            {
                                @for (var i = 0; i < securitySettings.Sessions.Count; i++)
                                {
                                    var session = securitySettings.Sessions[i];
                                    <tr>
                                        <td>@session.Device</td>
                                        <td>@session.Location</td>
                                        <td>@session.LastActive.ToString("g")</td>
                                        <td>
                                            @if (i > 0)
                                            {
                                                <button class="btn btn-danger btn-sm"
                                                        @onclick="() => ConfirmRevokeSession(session)">
                                                    Revoke
                                                </button>
                                            }
                                            else
                                            {
                                                <span class="current-badge">Current</span>
                                            }
                                        </td>
                                    </tr>
                                }
                            }
                        </tbody>
                    </table>
                </div>

                @if (showRevokeConfirmation)
                {
                    <div class="modal-overlay" @onclick="CancelRevoke">
                        <div class="modal-dialog" @onclick:stopPropagation>
                            <h3>Confirm Session Revocation</h3>
                            <p>Are you sure you want to revoke the session on <strong>@sessionToRevoke?.Device</strong> from <strong>@sessionToRevoke?.Location</strong>?</p>
                            <div class="button-group">
                                <button class="btn btn-danger" @onclick="RevokeSession">Revoke Session</button>
                                <button class="btn btn-secondary" @onclick="CancelRevoke">Cancel</button>
                            </div>
                        </div>
                    </div>
                }
            </section>
        }
        else if (activeSection == "Appearance")
        {
            <section class="settings-section">
                <h2>Appearance Settings</h2>

                <div class="form-group">
                    <label>Theme</label>
                    <div class="radio-group">
                        <label class="radio-label">
                            <input type="radio" name="theme" value="Light"
                                   checked="@(editAppearance.Theme == "Light")"
                                   @onchange='() => editAppearance.Theme = "Light"' /> Light
                        </label>
                        <label class="radio-label">
                            <input type="radio" name="theme" value="Dark"
                                   checked="@(editAppearance.Theme == "Dark")"
                                   @onchange='() => editAppearance.Theme = "Dark"' /> Dark
                        </label>
                        <label class="radio-label">
                            <input type="radio" name="theme" value="System"
                                   checked="@(editAppearance.Theme == "System")"
                                   @onchange='() => editAppearance.Theme = "System"' /> System
                        </label>
                    </div>
                </div>

                <div class="form-group">
                    <label>Font Size</label>
                    <div class="radio-group">
                        <label class="radio-label">
                            <input type="radio" name="fontSize" value="Small"
                                   checked="@(editAppearance.FontSize == "Small")"
                                   @onchange='() => editAppearance.FontSize = "Small"' /> Small
                        </label>
                        <label class="radio-label">
                            <input type="radio" name="fontSize" value="Medium"
                                   checked="@(editAppearance.FontSize == "Medium")"
                                   @onchange='() => editAppearance.FontSize = "Medium"' /> Medium
                        </label>
                        <label class="radio-label">
                            <input type="radio" name="fontSize" value="Large"
                                   checked="@(editAppearance.FontSize == "Large")"
                                   @onchange='() => editAppearance.FontSize = "Large"' /> Large
                        </label>
                    </div>
                </div>

                <div class="form-group">
                    <label for="language">Language</label>
                    <select id="language" @bind="editAppearance.Language">
                        <option value="en">English</option>
                        <option value="es">Spanish</option>
                        <option value="fr">French</option>
                        <option value="de">German</option>
                        <option value="ja">Japanese</option>
                        <option value="zh">Chinese</option>
                    </select>
                </div>

                <div class="toggle-group">
                    <label class="toggle-label">
                        <input type="checkbox" @bind="editAppearance.CompactMode" />
                        <span class="toggle-switch"></span>
                        Compact Mode
                    </label>
                </div>

                <h3>Live Preview</h3>
                <div class="live-preview @GetPreviewClasses()">
                    <div class="preview-header">Sample Header</div>
                    <p class="preview-text">This is how your content will look with the selected appearance settings.</p>
                    <button class="preview-button">Sample Button</button>
                </div>

                <div class="button-group">
                    <button class="btn btn-primary" @onclick="SaveAppearance">Save</button>
                </div>
            </section>
        }

        @if (!string.IsNullOrEmpty(toastMessage))
        {
            <div class="toast @toastType">
                @toastMessage
                <button class="toast-close" @onclick="DismissToast">✕</button>
            </div>
        }
    </main>
</div>

